import React, { useState, useEffect } from 'react';
import api from '../api';

function PaymentPage() {

    const [payments, setPayments] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [editingItem, setEditingItem] = useState(null);

    const [rentalId, setRentalId] = useState('');
    const [amount, setAmount] = useState('');
    const [paymentDate, setPaymentDate] = useState('');
    const [paymentMethod, setPaymentMethod] = useState('CASH');
    const [status, setStatus] = useState('PENDING');

    function fetchPayments() {

        setLoading(true);

        api.findAllPayments().then(function(response) {

            setPayments(response.data);
            setError('');
            setLoading(false);

        }).catch(function() {

            setError('Failed to fetch payments.');
            setLoading(false);

        });

    }

    useEffect(function() {
        fetchPayments();
    }, []);

    function resetForm() {

        setRentalId('');
        setAmount('');
        setPaymentDate('');
        setPaymentMethod('CASH');
        setStatus('PENDING');
        setEditingItem(null);

    }

    function openEditForm(payment) {

        setRentalId(payment.rentalId);
        setAmount(payment.amount);
        setPaymentDate(payment.paymentDate);
        setPaymentMethod(payment.paymentMethod);
        setStatus(payment.status);
        setEditingItem(payment);
        setShowForm(true);

    }

    function handleSubmit(e) {

        e.preventDefault();

        var amountValue = parseFloat(amount) || 0;

        const data = {
            rentalId: parseInt(rentalId) || 0,
            amount: amountValue,
            paymentDate: paymentDate,
            paymentMethod: paymentMethod,
            status: status
        };

        if (editingItem) {

            api.updatePayment(editingItem.id, data).then(function() {

                resetForm();
                setShowForm(false);
                fetchPayments();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to update payment.';
                setError(message);
            });

        } else {

            api.savePayment(data).then(function() {

                resetForm();
                setShowForm(false);
                fetchPayments();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to save payment.';
                setError(message);
            });

        }

    }

    function handleDelete(id) {

        var confirmed = window.confirm('Delete this payment record?');

        if (!confirmed) {
            return;
        }

        api.deletePayment(id).then(function() {
            fetchPayments();
        }).catch(function(err) {
            var message = err.response?.data?.message || 'Failed to delete payment.';
            setError(message);
        });

    }

    function getPaymentMethodLabel(method) {

        if (method === 'CASH') return 'Cash';
        if (method === 'CARD') return 'Card';
        if (method === 'MOBILE') return 'Mobile Money';
        return method;

    }

    function getStatusStyle(statusValue) {

        if (statusValue === 'COMPLETED') {
            return { bg: '#d1fae5', text: '#065f46' };
        }

        if (statusValue === 'PENDING') {
            return { bg: '#fef3c7', text: '#92400e' };
        }

        return { bg: '#fef2f2', text: '#dc2626' };

    }

    if (loading) {

        return (
            <div style={{ textAlign: 'center', padding: '2rem' }}>
                <p>Loading payments...</p>
            </div>
        );

    }

    return (

        <div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>

                <h2 style={{ margin: 0, color: '#1a1a2e' }}>Payments</h2>

                <button onClick={function() { resetForm(); setShowForm(true); }}
                    style={{ background: '#fbbf24', color: '#1a1a2e', border: 'none', padding: '0.5rem 1rem', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>
                    Add Payment
                </button>

            </div>

            {error && (

                <div style={{ background: '#fef2f2', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '8px', marginBottom: '1rem', display: 'flex', justifyContent: 'space-between' }}>

                    <span>Error: {error}</span>

                    <button onClick={function() { setError(''); }}
                        style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: 'bold' }}>
                        X
                    </button>

                </div>

            )}

            {showForm && (

                <div style={{ background: '#fff', borderRadius: '12px', padding: '1.5rem', marginBottom: '1.5rem', border: '1px solid #e5e7eb' }}>

                    <h3 style={{ margin: '0 0 1rem', color: '#1a1a2e' }}>
                        {editingItem ? 'Edit Payment' : 'Add New Payment'}
                    </h3>

                    <form onSubmit={handleSubmit}>

                        <div style={{ marginBottom: '0.8rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Rental ID
                            </label>

                            <input type="number" value={rentalId}
                                onChange={function(e) { setRentalId(e.target.value); }}
                                required
                                placeholder="e.g. 1"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '0.8rem' }}>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Amount (TSh)
                                </label>

                                <input type="number" value={amount}
                                    onChange={function(e) { setAmount(e.target.value); }}
                                    required
                                    placeholder="e.g. 45000"
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Payment Date
                                </label>

                                <input type="date" value={paymentDate}
                                    onChange={function(e) { setPaymentDate(e.target.value); }}
                                    required
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                            </div>

                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.8rem', marginBottom: '1rem' }}>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Payment Method
                                </label>

                                <select value={paymentMethod}
                                    onChange={function(e) { setPaymentMethod(e.target.value); }}
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', background: '#fff', boxSizing: 'border-box' }}>

                                    <option value="CASH">Cash</option>
                                    <option value="CARD">Card</option>
                                    <option value="MOBILE">Mobile Money</option>

                                </select>

                            </div>

                            <div>

                                <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                    Status
                                </label>

                                <select value={status}
                                    onChange={function(e) { setStatus(e.target.value); }}
                                    style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', background: '#fff', boxSizing: 'border-box' }}>

                                    <option value="PENDING">Pending</option>
                                    <option value="COMPLETED">Completed</option>
                                    <option value="FAILED">Failed</option>

                                </select>

                            </div>

                        </div>

                        <div style={{ display: 'flex', gap: '0.75rem' }}>

                            <button type="submit"
                                style={{ flex: 1, padding: '0.6rem', background: '#059669', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' }}>
                                {editingItem ? 'Update' : 'Save'}
                            </button>

                            <button type="button" onClick={function() { setShowForm(false); resetForm(); }}
                                style={{ padding: '0.6rem 1.2rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '8px', cursor: 'pointer' }}>
                                Cancel
                            </button>

                        </div>

                    </form>

                </div>

            )}

            {!showForm && payments.length === 0 && (

                <div style={{ textAlign: 'center', padding: '2rem', background: '#fff', borderRadius: '10px', border: '1px solid #e5e7eb' }}>

                    <p style={{ color: '#6b7280' }}>No payments recorded yet.</p>

                </div>

            )}

            {!showForm && payments.map(function(payment) {

                var statusStyle = getStatusStyle(payment.status);

                return (

                    <div key={payment.id}
                        style={{ background: '#fff', borderRadius: '10px', padding: '1rem', marginBottom: '0.75rem', border: '1px solid #e5e7eb' }}>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>

                            <div>

                                <div style={{ fontWeight: 600, color: '#111827' }}>
                                    Rental #{payment.rentalId} - TSh {payment.amount?.toLocaleString()}
                                </div>

                                <div style={{ fontSize: '0.85rem', color: '#6b7280', marginTop: '0.2rem' }}>
                                    Date: {payment.paymentDate} | Method: {getPaymentMethodLabel(payment.paymentMethod)}
                                </div>

                                <span style={{ background: statusStyle.bg, color: statusStyle.text, padding: '0.15rem 0.6rem', borderRadius: '12px', fontSize: '0.75rem', fontWeight: 500, display: 'inline-block', marginTop: '0.3rem' }}>
                                    {payment.status}
                                </span>

                            </div>

                            <div style={{ display: 'flex', gap: '0.4rem' }}>

                                <button onClick={function() { openEditForm(payment); }}
                                    style={{ background: '#fffbeb', color: '#92400e', border: '1px solid #fde68a', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                    Edit
                                </button>

                                <button onClick={function() { handleDelete(payment.id); }}
                                    style={{ background: '#fef2f2', color: '#dc2626', border: '1px solid #fecaca', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                    Delete
                                </button>

                            </div>

                        </div>

                    </div>

                );

            })}

        </div>

    );

}

export default PaymentPage;
